import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"惜誓","description":"","frontmatter":{"title":"惜誓","date":"2026-11-24T00:00:00.000Z","seq":29,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"贾谊","source_book":"楚辞","prev":{"text":"大招","link":"/blogs/楚辞/大招.html"},"next":{"text":"招隐士","link":"/blogs/楚辞/招隐士.html"}},"headers":[],"relativePath":"blogs/楚辞/惜誓.md","filePath":"blogs/楚辞/惜誓.md"}'),o={name:"blogs/楚辞/惜誓.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="惜誓" tabindex="-1">惜誓 <a class="header-anchor" href="#惜誓" aria-label="Permalink to &quot;惜誓&quot;">​</a></h1><p class="poem-meta">先秦 · 贾谊　·　惜誓</p><div class="poem"><p class="poem-stanza">惜余年老而日衰兮，岁忽忽而不反。</p><p class="poem-stanza">登苍天而高举兮，历众山而日远。</p><p class="poem-stanza">观江河之纡曲兮，离四海之霑濡。</p><p class="poem-stanza">攀北极而一息兮，吸沆瀣以充虚。</p><p class="poem-stanza">飞朱鸟使先驱兮，驾太一之象舆。</p><p class="poem-stanza">苍龙蚴虯于左骖兮，白虎骋而为右騑。</p><p class="poem-stanza">建日月以为盖兮，载玉女于後车。</p><p class="poem-stanza">驰骛于杳冥之中兮，休息虖昆仑之墟。</p><p class="poem-stanza">乐穷极而不厌兮，愿从容虖神明。</p><p class="poem-stanza">涉丹水而驰骋兮，右大夏之遗风。</p><p class="poem-stanza">黄鹄之一举兮，知山川之纡曲。</p><p class="poem-stanza">再举兮，睹天地之圜方。</p><p class="poem-stanza">临中国之众人兮，讬回飙乎尚羊。</p><p class="poem-stanza">乃至少原之野兮，赤松、王乔皆在旁。</p><p class="poem-stanza">二子拥瑟而调均兮，余因称乎清商。</p><p class="poem-stanza">澹然而自乐兮，吸众气而翱翔。</p><p class="poem-stanza">念我长生而久仙兮，不如反余之故乡。</p><p class="poem-stanza">黄鹄後时而寄处兮，鸱枭群而制之。</p><p class="poem-stanza">神龙失水而陆居兮，为蝼蚁之所裁。</p><p class="poem-stanza">夫黄鹄神龙犹如此兮，况贤者之逢乱世哉。</p><p class="poem-stanza">寿冉冉而日衰兮，固儃回而不息。</p><p class="poem-stanza">俗流从而不止兮，众枉聚而矫直。</p><p class="poem-stanza">或偷合而苟进兮，或隐居而深藏。</p><p class="poem-stanza">苦称量之不审兮，同权概而就衡。</p><p class="poem-stanza">或推迻而苟容兮，或直言之谔謣。</p><p class="poem-stanza">伤诚是之不察兮，并纫茅丝以为索。</p><p class="poem-stanza">方世俗之幽昏兮，眩白黑之美恶。</p><p class="poem-stanza">放山渊之龟玉兮，相与贵夫砾石。</p><p class="poem-stanza">梅伯数谏而至醢兮，来革顺志而用国。</p><p class="poem-stanza">悲仁人之尽节兮，反为小人之所贼。</p><p class="poem-stanza">比干忠谏而剖心兮，箕子被发而佯狂。</p><p class="poem-stanza">水背流而源竭兮，木去根而不长。</p><p class="poem-stanza">非重躯以虑难兮，惜伤身之无功。</p><p class="poem-stanza">已矣哉！独不见夫鸾凤之高翔兮，乃集大皇之野。</p><p class="poem-stanza">循四极而回周兮，见盛德而後下。</p><p class="poem-stanza">彼圣人之神德兮，远浊世而自藏。</p><p class="poem-stanza">使麒麟可得羁而係兮，又何以异虖犬羊？</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
